  final newIds = widget.selectedTags.map((t) => t.id).toList();
  if (oldIds.length != newIds.length) {
    _selectedTags = List<TopicTag>.from(widget.selectedTags);
    return;
  }
  for (var i = 0; i < oldIds.length; i++) {
    if (oldIds[i] != newIds[i]) {
      _selectedTags = List<TopicTag>.from(widget.selectedTags);
      return;
    }
  }
}

